                        strip_blank_front(&p);

                        /*
                         * new section, break out and make sure we don't
                         * fgets() a new line at the top.
                         */
                        if (p[0] == '[') {
                                if (nested) {
                                        log_err("No new sections in included files\n");
                                        ret = 1;
                                        goto out;
                                }

                                skip_fgets = 1;
                                break;
                        }

                        strip_blank_end(p);

                        if (!strncmp(p, "include", strlen("include"))) {
                                char *filename = p + strlen("include") + 1,
                                        *ts, *full_fn = NULL;

                                /*
                                 * Allow for the include filename
                                 * specification to be relative.
                                 */
                                if (access(filename, F_OK) &&
                                    (ts = strrchr(file, '/'))) {
                                        if (asprintf(&full_fn, "%.*s%s",
                                                 (int)(ts - file + 1), file,
                                                 filename) < 0) {
                                                ret = ENOMEM;
                                                break;
                                        }
                                        filename = full_fn;
                                }

                                ret = __parse_jobs_ini(td, filename, is_buf,
                                                       stonewall_flag, type, 1,
                                                       name, &opts,
                                                       &alloc_opts, &num_opts);

                                if (ret) {
                                        log_err("Error %d while parsing "
                                                "include file %s\n",
                                                ret, filename);
                                }

                                if (full_fn)
                                        free(full_fn);

                                if (ret)
                                        break;

                                continue;
                        }

                        if (num_opts == alloc_opts) {
                                alloc_opts <<= 1;
                                opts = realloc(opts,
                                                alloc_opts * sizeof(char *));
                        }

                        opts[num_opts] = strdup(p);
                        num_opts++;
                }

                if (nested) {
                        *popts = opts;
                        *aopts = alloc_opts;
                        *nopts = num_opts;
                        goto out;
                }

                ret = fio_options_parse(td, opts, num_opts);

                if (!ret && td->o.read_iolog_file != NULL) {
                        char *fname = get_name_by_idx(td->o.read_iolog_file,
                                                      td->subjob_number);
                        if (!strcmp(fname, "-")) {
                                if (stdin_occupied) {
                                        log_err("fio: only one user (read_iolog_file/job "
                                                "file) of stdin is permitted at once but "
                                                "more than one was found.\n");
                                        ret = 1;
                                }
                                stdin_occupied = true;
                        }
                }
                if (!ret) {
                        if (dump_cmdline)
                                dump_opt_list(td);

                        ret = add_job(td, name, 0, 0, type);
                } else {
                        log_err("fio: job %s dropped\n", name);
                        put_job(td);
                }

                for (i = 0; i < num_opts; i++)
                        free(opts[i]);
                num_opts = 0;
        } while (!ret);

        if (dump_cmdline)
                log_info("\n");

        i = 0;
        while (i < nr_job_sections) {
                free(job_sections[i]);
                i++;
        }

        free(opts);
out:
        free(string);
        if (!nested)
                free(name);
        if (!is_buf && f != stdin)
                fclose(f);
        return ret;
}

